// Real LAB TEST Auth, NestJS, PostgreSQL/RLS and Docker SUBMIT. No progress stubs.
import type { Session } from '@supabase/supabase-js';
import type {
  AcademicClass,
  Activity,
  Attempt,
  Concept,
  Exercise,
  JoinCode,
  StudentProgress,
} from '@alunza/contracts';
import identityFixture from '../../fixtures/foundation/identity.json';
import { instantMicros, progressAfterPublications } from './progress-clock.mjs';

const organizationId = identityFixture.organizations[0]!.id;
const courseId = '30000000-0000-4000-8000-000000000001';
type Context = {
  admin: Session;
  teacher: Session;
  student: Session;
  outsider: Session;
  classroom: AcademicClass;
  concepts: Concept[];
  activities: Activity[];
  success: Attempt;
  beforeSuccess: string;
};

function rest<T extends object>(
  session: Session,
  method: 'GET' | 'POST',
  path: string,
  body?: Record<string, unknown>,
  revision?: number,
): Cypress.Chainable<T> {
  return cy
    .env(['apiBaseUrl'], { log: false })
    .then(({ apiBaseUrl }) =>
      cy.request<{ data: T }>({
        method,
        url: `${apiBaseUrl}/api/v1${path}`,
        body,
        log: false,
        timeout: 45_000,
        headers: {
          Authorization: `Bearer ${session.access_token}`,
          'Idempotency-Key': crypto.randomUUID(),
          ...(revision ? { 'If-Match': `"${revision}"` } : {}),
        },
      }),
    )
    .then((response) => {
      expect(response.status).to.be.within(200, 299);
      return cy.wrap(response.body.data, { log: false });
    });
}

function setup(academicStudent: number): Cypress.Chainable<Context> {
  const suffix = crypto.randomUUID().slice(0, 8);
  const context = { concepts: [], activities: [] } as unknown as Context;
  const exercises: Exercise[] = [];
  return cy
    .task<Session>('identity:login', 'ADMIN', { log: false })
    .then((session) => {
      context.admin = session;
      return cy.task<Session>('identity:login', 'TEACHER', { log: false });
    })
    .then((session) => {
      context.teacher = session;
      return cy.task<Session>(
        'identity:login',
        { role: 'STUDENT', academicStudent },
        { log: false },
      );
    })
    .then((session) => {
      context.student = session;
      return cy.task<Session>('identity:login', 'STUDENT', { log: false });
    })
    .then((session) => {
      context.outsider = session;
      return rest<AcademicClass>(
        context.teacher,
        'POST',
        `/organizations/${organizationId}/classes`,
        {
          courseId,
          code: `PROGRESS-${suffix}`,
          name: `Clase progreso ${suffix}`,
          description: 'Fixture ficticio de progreso',
          startDate: '2026-08-01',
          endDate: '2026-12-31',
        },
      );
    })
    .then((classroom) => {
      context.classroom = classroom;
      return cy.wrap([0, 1]).each((_value, index) =>
        rest<Concept>(
          context.admin,
          'POST',
          `/organizations/${organizationId}/concepts`,
          {
            name: `Concepto ${index} progreso ${suffix}`,
            description: 'Operaciones y argumentos',
            parentId: null,
          },
        ).then((concept) => {
          context.concepts.push(concept);
        }),
      );
    })
    .then(() =>
      cy.wrap([0, 1]).each((_value, index) =>
        rest<Exercise>(
          context.teacher,
          'POST',
          `/organizations/${organizationId}/exercises`,
          {
            title: `Ejercicio ${index} progreso ${suffix}`,
            statement: 'Devuelve la suma de los dos argumentos.',
            starterCode: 'module.exports.solve=(a,b)=>0;',
            language: 'javascript',
            entrypoint: 'solve',
            difficulty: 'BEGINNER',
            conceptVersionIds:
              index === 0
                ? context.concepts.map((item) => item.currentVersionId)
                : [context.concepts[1]!.currentVersionId],
            tests: [
              {
                id: 'progress-visible',
                visibility: 'visible',
                args: [2, 3],
                expected: 5,
              },
              {
                id: 'progress-hidden',
                visibility: 'hidden',
                args: [19, 23],
                expected: 42,
              },
            ],
            executionLimits: {
              memoryBytes: 134217728,
              runtimeMs: 3000,
              outputBytes: 65536,
            },
          },
        ).then((exercise) => {
          exercises.push(exercise);
        }),
      ),
    )
    .then(() =>
      cy.wrap([0, 1, 2]).each((_value, index) =>
        rest<Activity>(
          context.teacher,
          'POST',
          `/classes/${context.classroom.id}/activities`,
          {
            title: `Actividad ${index} progreso ${suffix}`,
            instructions: 'Practica con evidencia determinista.',
            type: 'FORMATIVE',
            opensAt: null,
            closesAt: null,
            exercises: (index === 0
              ? exercises
              : index === 1
                ? [exercises[0]!]
                : [exercises[1]!, exercises[0]!]
            ).map((item, position) => ({
              exerciseVersionId: item.currentVersionId,
              position,
              required: index !== 2 || position === 0,
            })),
          },
        )
          .then((activity) =>
            rest<Activity>(
              context.teacher,
              'POST',
              `/activities/${activity.id}/publish`,
              {},
              activity.revision,
            ),
          )
          .then((activity) => {
            context.activities.push(activity);
          }),
      ),
    )
    .then(() =>
      rest<JoinCode>(
        context.teacher,
        'POST',
        `/classes/${context.classroom.id}/join-codes`,
        {},
        context.classroom.revision,
      ),
    )
    .then((code) =>
      rest(context.student, 'POST', '/class-enrollments', { code: code.code }),
    )
    .then(() =>
      progressAfterPublications(
        () =>
          rest<StudentProgress>(
            context.student,
            'GET',
            `/me/progress?classId=${context.classroom.id}`,
          ),
        context.activities.map((activity) => activity.publishedAt),
      ),
    )
    .then((progress) => {
      expect(progress.summary).to.include({ completed: 0, required: 4 });
      context.beforeSuccess = progress.asOf;
      const activity = context.activities[0]!;
      return rest<Attempt>(
        context.student,
        'POST',
        `/activities/${activity.id}/exercises/${activity.exercises[0]!.id}/attempts`,
        {
          exerciseVersionId: activity.exercises[0]!.exerciseVersionId,
          code: 'module.exports.solve=(a,b)=>a+b;',
        },
      );
    })
    .then((attempt) => {
      expect(
        instantMicros(attempt.submittedAt) >
          instantMicros(context.beforeSuccess),
        'The server clock must keep this later SUBMIT outside the fixture cutoff',
      ).to.equal(true);
      context.success = attempt;
      return cy.wrap(context, { log: false });
    });
}
function visitAs(session: Session, path: string) {
  return cy.visit(path, {
    onBeforeLoad(window) {
      window.localStorage.setItem(
        'alunza.auth.127.0.0.1:18421',
        JSON.stringify(session),
      );
    },
  });
}
function progressPath(context: Context) {
  return `/clases/${context.classroom.id}/progreso`;
}

describe('IMP-05 · Progreso personal acumulado y eventos explícitos', () => {
  let index = 0;
  beforeEach(() => {
    setup(index++ % 3).as('progress');
  });

  it('IMP05-01 · HU015-E1/E4 · Filtrar actividad y concepto → conserva fracciones, evidencia y ausencia de requeridos', () => {
    cy.get<Context>('@progress').then((context) => {
      visitAs(context.student, progressPath(context));
      cy.get('[data-cy="progress-summary"]')
        .should('contain.text', '1/4')
        .and('contain.text', '25 %');
      cy.get('[data-cy="progress-concept-row"]')
        .contains('h3', context.concepts[0]!.name)
        .closest('[data-cy="progress-concept-row"]')
        .should('contain.text', '1/2');
      cy.get('[data-cy="progress-evidence-row"]').should('have.length', 1);
      cy.get('[data-cy="progress-show-attempt"]').click();
      cy.get('[data-cy="attempt-id"]').should(
        'contain.text',
        context.success.attemptId,
      );
      cy.get('[data-cy="attempt-diagnosis"]').should('contain.text', 'SUCCESS');
      cy.get('[role="dialog"] button[aria-label="Cerrar diálogo"]').click();
      cy.get('#progress-concept')
        .focus()
        .should('be.focused')
        .select(context.concepts[0]!.id);
      cy.get('[data-cy="progress-filters"]')
        .contains('button', 'Aplicar filtros')
        .click();
      cy.get('[data-cy="progress-summary"]')
        .should('contain.text', '1/2')
        .and('contain.text', '50 %');
      cy.get('#progress-concept').select('');
      cy.get('#progress-activity').select(context.activities[1]!.id);
      cy.get('[data-cy="progress-filters"]')
        .contains('button', 'Aplicar filtros')
        .click();
      cy.get('[data-cy="progress-summary"]')
        .should('contain.text', '0/1')
        .and('contain.text', 'Sin intentos');
      cy.get('#progress-activity').select(context.activities[2]!.id);
      cy.get('#progress-concept').select(context.concepts[0]!.id);
      cy.get('[data-cy="progress-filters"]')
        .contains('button', 'Aplicar filtros')
        .click();
      cy.get('[data-cy="progress-summary"]')
        .should('contain.text', '0/0')
        .and('contain.text', 'No calculable')
        .and('not.contain.text', '0 %');
    });
  });

  it('IMP05-02 · HU015-E1/E2 · Consultar cortes y reintentar una falla real → conserva el éxito y distingue error de cero', () => {
    cy.get<Context>('@progress').then((context) => {
      rest<StudentProgress>(
        context.student,
        'GET',
        `/me/progress?classId=${context.classroom.id}&asOf=${encodeURIComponent(context.beforeSuccess)}`,
      ).then((value) =>
        expect(value.summary).to.include({ completed: 0, required: 4 }),
      );
      rest<StudentProgress>(
        context.student,
        'GET',
        `/me/progress?classId=${context.classroom.id}&asOf=${encodeURIComponent(context.success.submittedAt)}`,
      ).then((value) =>
        expect(value.summary).to.include({ completed: 1, required: 4 }),
      );
      const activity = context.activities[0]!;
      rest(
        context.student,
        'POST',
        `/activities/${activity.id}/exercises/${activity.exercises[0]!.id}/attempts`,
        {
          exerciseVersionId: activity.exercises[0]!.exerciseVersionId,
          code: 'module.exports.solve=()=>0;',
        },
      );
      visitAs(context.student, progressPath(context));
      cy.get('[data-cy="progress-summary"]').should('contain.text', '1/4');
      cy.task('foundation:apiStop', null, { log: false });
      cy.get('[data-cy="progress-filters"]')
        .contains('button', 'Aplicar filtros')
        .click();
      cy.get('[data-cy="student-progress"] [role="alert"]').should(
        'be.visible',
      );
      cy.get('[data-cy="progress-summary"]').should('not.exist');
      cy.task('foundation:apiStart', null, { log: false });
      cy.get('[data-cy="student-progress"]')
        .contains('button', 'Reintentar consulta')
        .last()
        .click();
      cy.get('[data-cy="progress-summary"]').should('contain.text', '1/4');
      cy.get('#progress-cut').type('2020-01-01T12:00');
      cy.get('[data-cy="progress-filters"]')
        .contains('button', 'Aplicar filtros')
        .click();
      cy.get('[data-cy="progress-summary"]')
        .should('contain.text', '0/0')
        .and('contain.text', 'No calculable');
      const reused = context.activities[1]!;
      rest(
        context.student,
        'POST',
        `/activities/${reused.id}/exercises/${reused.exercises[0]!.id}/attempts`,
        {
          exerciseVersionId: reused.exercises[0]!.exerciseVersionId,
          code: 'module.exports.solve=(a,b)=>a+b;',
        },
      );
      // Resetting a historical cutoff must fetch a new current snapshot, not
      // reuse the older response that only supplied filter choices.
      cy.intercept(
        'GET',
        `**/api/v1/me/progress?classId=${context.classroom.id}`,
      ).as('currentProgress');
      cy.get('#progress-cut').clear();
      cy.get('[data-cy="progress-filters"]')
        .contains('button', 'Aplicar filtros')
        .click();
      cy.wait('@currentProgress')
        .its('response.body.data.summary.completed')
        .should('equal', 2);
      cy.get('[data-cy="progress-summary"]').should('contain.text', '2/4');
    });
  });

  it('IMP05-03 · HU015-E3 · Cambiar cuenta y abrir una clase ajena → no muestra progreso ni intentos privados', () => {
    cy.get<Context>('@progress').then((context) => {
      visitAs(context.admin, `/clases/${context.classroom.id}`);
      cy.get('[data-cy="open-student-progress"]').should('not.exist');
      cy.visit(progressPath(context));
      cy.get('[role="alert"]').should('be.visible');
      cy.get('[data-cy="progress-summary"]').should('not.exist');
      visitAs(context.outsider, progressPath(context));
      cy.get('[role="alert"]').should('be.visible');
      cy.get('[data-cy="progress-evidence-row"]').should('not.exist');
      cy.contains(context.success.attemptId).should('not.exist');
    });
  });

  it('IMP05-04 · DEC005 · Abrir explícitamente y actualizar la página → registra visitas nuevas y deduplica refresh y recarga técnica', () => {
    cy.get<Context>('@progress').then((context) => {
      const activity = context.activities[0]!;
      const keys: string[] = [];
      cy.intercept(
        'POST',
        `**/api/v1/activities/${activity.id}/open-events`,
        (request) => {
          keys.push(String(request.headers['idempotency-key']));
        },
      ).as('opened');
      visitAs(context.student, `/clases/${context.classroom.id}`);
      cy.get('[data-cy="activity-card"]')
        .contains('h2', activity.title)
        .closest('[data-cy="activity-card"]')
        .contains('a', 'Abrir actividad')
        .click();
      cy.wait('@opened')
        .its('response.statusCode')
        .should('be.within', 200, 299);
      cy.window()
        .its('history.state.alunzaActivityVisitV1.confirmed')
        .should('equal', true);
      cy.get('[data-cy="published-exercise"]').should('have.length', 2);
      cy.reload();
      cy.get('[data-cy="published-exercise"]').should('have.length', 2);
      cy.get('[data-cy="published-exercise"]')
        .first()
        .contains('a', 'Abrir ejercicio')
        .click();
      cy.wait('@opened')
        .its('response.statusCode')
        .should('be.within', 200, 299);
      cy.window()
        .its('history.state.alunzaActivityVisitV1.confirmed')
        .should('equal', true);
      cy.get('[data-cy="student-code"]').should('be.visible');
      cy.contains('button', 'Actualizar disponibilidad').click();
      cy.get('[data-cy="student-code"]').should('not.have.attr', 'readonly');
      cy.then(() => {
        expect(keys).to.have.length(2);
        expect(new Set(keys).size).to.equal(2);
      });
      cy.go('back');
      cy.get('[data-cy="published-exercise"]').should('have.length', 2);
      cy.then(() => expect(keys).to.have.length(2));
      cy.get('[data-cy="published-exercise"]')
        .first()
        .contains('a', 'Abrir ejercicio')
        .click();
      cy.wait('@opened');
      cy.then(() => {
        expect(keys).to.have.length(3);
        expect(new Set(keys).size).to.equal(3);
      });
    });
  });
});
